def factorial(n):
    if not isinstance(n, int):
        raise TypeError("n 必须是非负整数或整数类型")
    if n < 0:
        raise ValueError("n 不能为负数")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

import re

def is_palindrome(text):
    if text is None:
        return False
    s = re.sub(r'[^A-Za-z0-9]+', '', str(text)).lower()
    return s == s[::-1]

def clamp(value, lower, upper):
    if lower > upper:
        raise ValueError("lower must be less than or equal to upper")
    if value < lower:
        return lower
    if value > upper:
        return upper
    return value

def count_vowels(text):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    text = text.lower()
    return sum(1 for ch in text if ch in vowels)

from typing import Iterable, List, TypeVar

T = TypeVar("T")

def deduplicate(items: Iterable[T]) -> List[T]:
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
